package country

// countries_gen.go holds data/countries.json (generated by tools/gencountries)
// as Go tables. Regenerate it after the JSON changes:
//
//go:generate go run ../../tools/gencountrygo -in data/countries.json -out countries_gen.go

// defaultStore is built from the generated tables. The tables are static
// data, so only the slice of pointers into countryTable is made at start.
var defaultStore = newStore(tablePointers(), countryIndex[:], generatedAt, source)

func tablePointers() []*Country {
	ptrs := make([]*Country, len(countryTable))
	for i := range countryTable {
		ptrs[i] = &countryTable[i]
	}
	return ptrs
}

// Default returns the store of the bundled country data. Every call returns
// the same store.
func Default() *Store {
	return defaultStore
}
